    const remote=await response.json();state.knowledgeSearchResults=null;state.knowledgeSearchMode="";const keys=["chat","conversations","tasks","goals","knowledge","projects","researchDrafts","workspaceHistory","learningPlans","labDrafts","skills","skillRuns"];
