  function validateAppearance(value){const a=value&&typeof value==="object"?value:{};return{fontSize:[13,15,17,19].includes(Number(a.fontSize))?Number(a.fontSize):15,radius:[8,12,18,24].includes(Number(a.radius))?Number(a.radius):12,sidebar:["solid","subtle","bordered"].includes(a.sidebar)?a.sidebar:"solid",message:["soft","outlined","minimal"].includes(a.message)?a.message:"soft",contrast:a.contrast==="high"?"high":"normal",motion:["system","reduced","full"].includes(a.motion)?a.motion:"system",dimension:["2d","3d"].includes(a.dimension)?a.dimension:"2d",motif:["flow","orbital","crystal","glass","skeuomorphic","minimal"].includes(a.motif)?a.motif:"flow",depthComponents:Array.isArray(a.depthComponents)?a.depthComponents.filter(x=>["panels","messages","buttons","navigation","background"].includes(x)):["panels","messages","buttons","navigation","background"],motifIntensity:Number.isFinite(Number(a.motifIntensity))?Math.max(0,Math.min(100,Number(a.motifIntensity))):45,depthStrength:Number.isFinite(Number(a.depthStrength))?Math.max(0,Math.min(100,Number(a.depthStrength))):55};}
