  const APPEARANCE_WORKSPACES={home:"Home",chat:"Chat",tasks:"Tasks & Goals",projects:"Projects",research:"Research",knowledge:"Knowledge",learning:"Learning & Skills",lab:"R&D Lab",coding:"Coding & IDE",progress:"Progress"};
  function validateWorkspaceAppearance(value){const out={};if(!value||typeof value!=="object"||Array.isArray(value))return out;for(const [key,v] of Object.entries(value)){if(!Object.hasOwn(APPEARANCE_WORKSPACES,key)||!v||typeof v!=="object")continue;const theme=typeof v.theme==="string"&&(Object.hasOwn(THEME_PRESETS,v.theme)||v.theme==="system"||state.customThemes?.some(t=>t.name===v.theme))?v.theme:"global";const accent=typeof v.accent==="string"&&/^#[0-9a-fA-F]{6}$/.test(v.accent)?v.accent.toLowerCase():"";const density=["Compact","Comfortable","Spacious"].includes(v.density)?v.density:"global";const layout=["default","compact","focused"].includes(v.layout)?v.layout:"default";out[key]={theme,accent,density,layout};}return out;}
