  async function extractImageTheme(file){
    const input=$("#themeSourceImage"),button=$("#extractImageTheme"),preview=$("#themeSourcePreview"),image=$("#themeSourcePreviewImage"),status=$("#themeSourcePaletteStatus"),report=$("#themeDnaReport"),nameField=$("#customThemeName");
    if(!file)return;
    try{
      if(!/^image\/(png|jpeg|webp|gif|avif)$/.test(file.type)||file.size>12*1024*1024)throw new Error("Choose a supported image smaller than 12 MB.");
      if(!window.createImageBitmap)throw new Error("This browser cannot analyze image structure locally.");
      if(status)status.textContent="Reading composition and visual structure locally…";
      const bitmap=await createImageBitmap(file,{imageOrientation:"from-image"});
      try{
        const canvas=document.createElement("canvas"),w=128,h=Math.max(1,Math.min(128,Math.round(128*bitmap.height/bitmap.width)));canvas.width=w;canvas.height=h;
        const ctx=canvas.getContext("2d",{willReadFrequently:true});if(!ctx)throw new Error("Image analysis is unavailable.");ctx.drawImage(bitmap,0,0,w,h);
        const data=ctx.getImageData(0,0,w,h).data,gray=new Float32Array(w*h);let sum=0,sumSq=0,edge=0,edgeN=0,empty=0,symmetry=0,symN=0;
        for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4,g=.2126*data[i]+.7152*data[i+1]+.0722*data[i+2];gray[y*w+x]=g;sum+=g;sumSq+=g*g;}
        const mean=sum/(w*h),variance=Math.max(0,sumSq/(w*h)-mean*mean),sd=Math.sqrt(variance);
        for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x,g=gray[i],gx=Math.abs(gray[i+1]-gray[i-1]),gy=Math.abs(gray[i+w]-gray[i-w]);edge+=Math.min(255,gx+gy);edgeN++;if(x<w/2){symmetry+=Math.abs(g-gray[y*w+(w-1-x)]);symN++;}if(Math.abs(g-mean)<sd*.22)empty++;}
        const edgeDensity=edgeN?edge/edgeN/255:0,whitespace=empty/(w*h),symmetryScore=symN?1-symmetry/symN/255:0,ratio=bitmap.width/bitmap.height;
        const geometric=edgeDensity>.16,quiet=edgeDensity<.075,balanced=symmetryScore>.78,wide=ratio>1.45,tall=ratio<.72;
        const radius=geometric?8:quiet?24:18, density=whitespace>.54?"Spacious":edgeDensity>.15?"Compact":"Comfortable",sidebar=balanced?"bordered":quiet?"subtle":"solid",message=geometric?"outlined":quiet?"minimal":"soft",font=whitespace>.58?17:edgeDensity>.18?13:15,layout=wide?"focused":tall?"compact":"default";
        const radiusField=$("#radiusScale"),sidebarField=$("#sidebarStyle"),messageField=$("#messageStyle"),fontField=$("#fontScale"),densityField=$("#densitySelect");
        if(radiusField)radiusField.value=String(radius);if(sidebarField)sidebarField.value=sidebar;if(messageField)messageField.value=message;if(fontField)fontField.value=String(font);const dimensionField=$("#dimensionMode"),motifField=$("#motifStyle");if(dimensionField)dimensionField.value="3d";if(motifField)motifField.value="flow";state.appearance=validateAppearance({...state.appearance,dimension:"3d",motif:"flow",motifIntensity:Math.round(Math.max(.2,Math.min(.8,edgeDensity*3+.2))*100),depthStrength:Math.round(Math.max(.3,Math.min(.8,sd/100+.3))*100)});
        if(densityField)densityField.value=density;
        const labels=[];labels.push(wide?"wide, cinematic composition":tall?"portrait, vertical composition":"balanced composition");labels.push(quiet?"low visual density":geometric?"high-detail, edge-rich structure":"moderate visual density");labels.push(balanced?"strong symmetry":"asymmetric / organic balance");labels.push(whitespace>.54?"generous negative space":whitespace<.25?"dense information field":"moderate negative space");labels.push("flowing ribbon contours");labels.push("layered depth and soft shadows");
        if(nameField&&!nameField.value.trim())nameField.value=file.name.replace(/\.[^.]+$/," ").trim().slice(0,40)||"Visual DNA theme";
        if(image){image.src=URL.createObjectURL(file);image.alt="Selected image used as a visual design reference";}if(preview)preview.hidden=false;
        if(report){report.hidden=false;report.innerHTML='<strong>Visual DNA profile</strong><div class="theme-dna-traits">'+labels.map(x=>'<span>'+escapeHTML(x)+'</span>').join('')+'</div><p>Proposed interface traits: <b>'+({8:"crisp corners",18:"balanced curves",24:"soft, rounded forms"}[radius])+'</b>, <b>'+density.toLowerCase()+' spacing</b>, <b>'+message+'</b> surfaces, <b>'+sidebar+'</b> navigation, and a <b>'+layout+'</b> workspace layout.</p><small>These are local structural heuristics, not semantic vision understanding. They change layout/style controls; no image colors are extracted.</small>';}
        if(status)status.textContent="Visual structure analyzed. Review the proposed design traits below.";
        // Apply the suggested layout/density immediately as a preview, without changing saved preferences yet.
        root.dataset.workspaceLayout=layout;root.dataset.dimension="3d";root.dataset.motif="flow";applyDensity(density);applyAppearance();toast("Visual DNA analyzed. Review the proposed structure and save appearance settings.");
      }finally{bitmap.close();}
    }catch(error){if(status)status.textContent=error.message||"Could not analyze this image.";toast("Visual DNA analysis failed: "+(error.message||"unsupported image."));}
    finally{if(button)button.disabled=!input?.files?.length;}
  }
  function readCustomThemeForm(){const name=$("#customThemeName")?.value.trim().slice(0,40)||"";if(!name)return null;const theme={name};for(const key of CUSTOM_COLOR_KEYS){const id={bg:"customBg",surface:"customSurface",surface2:"customSurface2",text:"customText",muted:"customMuted",line:"customLine",sidebar:"customSidebar",bubble:"customBubble",accent:"customAccent"}[key];const value=$("#"+id)?.value;if(!/^#[0-9a-fA-F]{6}$/.test(value||""))return null;theme[key]=value.toLowerCase();}return theme;}
  function updateCustomThemePreview(){const preview=$("#customThemePreview");if(!preview)return;const t=readCustomThemeForm();if(!t)return;preview.style.background=t.bg;preview.style.color=t.text;preview.style.borderColor=t.line;preview.querySelector("span").style.color=t.muted;const button=preview.querySelector("button");button.style.background=t.accent;button.style.color=t.bg;button.style.borderColor=t.accent;preview.style.setProperty("--preview-surface",t.surface);}
  function renderCustomThemeList(){const list=$("#customThemeList");if(!list)return;list.innerHTML=(state.customThemes||[]).map(t=>'<div class="custom-theme-row"><span class="custom-theme-dot" style="background:'+t.accent+'"></span><div class="custom-theme-meta"><strong>'+escapeHTML(t.name)+'</strong><small>'+t.bg+' · '+t.accent+'</small></div><button class="soft-button" data-action="apply-custom-theme" data-theme-name="'+escapeHTML(t.name)+'">Apply</button><button class="soft-button" data-action="edit-custom-theme" data-theme-name="'+escapeHTML(t.name)+'">Edit</button><button class="soft-button" data-action="duplicate-custom-theme" data-theme-name="'+escapeHTML(t.name)+'">Duplicate</button><button class="soft-button" data-action="delete-custom-theme" data-theme-name="'+escapeHTML(t.name)+'">Delete</button></div>').join("")||'<p class="muted">No custom themes saved yet.</p>';}
  async function importCustomThemes(file){if(!file)return;try{if(file.size>100000)throw new Error("Theme file must be smaller than 100 KB.");const payload=JSON.parse(await file.text());if(payload?.format!=="sparkle-gen3-themes"||payload?.version!==1||!Array.isArray(payload.themes))throw new Error("Unsupported theme file format.");const themes=validateCustomThemes(payload.themes);if(!themes.length||themes.length!==payload.themes.length)throw new Error("Theme file contains invalid palettes.");const merged=[...(state.customThemes||[])];for(const t of themes){const i=merged.findIndex(x=>x.name.toLowerCase()===t.name.toLowerCase());if(i>=0)merged[i]=t;else if(merged.length<24)merged.push(t);}state.customThemes=merged.slice(0,24);localStorage.setItem("sparkle-custom-themes",JSON.stringify(state.customThemes));persist();render();toast("Imported "+themes.length+" validated theme(s).");}catch(error){toast("Theme import failed: "+error.message);}}
  function updateGraphTangent(panel){const slider=$("[data-tangent-slider]",panel),figure=panel?.closest(".answer-line-graph"),svg=$(".answer-graph-svg",figure);if(!slider||!svg)return;const a=Number(slider.value),minX=Number(panel.dataset.minX),maxX=Number(panel.dataset.maxX),minY=Number(panel.dataset.minY),maxY=Number(panel.dataset.maxY),spanX=maxX-minX||1,spanY=maxY-minY||1,mapX=x=>28+((x-minX)/spanX)*344,mapY=y=>156-((y-minY)/spanY)*128,line=$("[data-tangent-line]",svg),point=$("[data-tangent-point]",svg);if(line)line.setAttribute("d","M "+mapX(minX).toFixed(2)+" "+mapY(2*a*minX-a*a).toFixed(2)+" L "+mapX(maxX).toFixed(2)+" "+mapY(2*a*maxX-a*a).toFixed(2));if(point){point.setAttribute("cx",mapX(a));point.setAttribute("cy",mapY(a*a));}const output=$("[data-tangent-value]",panel),slope=$("[data-tangent-slope]",panel);if(output)output.textContent=a.toFixed(1);if(slope)slope.textContent="At x = "+a.toFixed(1)+", slope f′(x) = "+(2*a).toFixed(1);}
