  function renderGlobalSearch(query){let box=$(".global-search-results");if(!String(query||"").trim()){box?.remove();return;}const q=String(query).trim().toLowerCase();const sources=[["Knowledge",state.knowledge||[],"knowledge",x=>[x.title,x.content]],["Tasks",state.tasks||[],"tasks",x=>[x.title,x.details]],["Goals",state.goals||[],"tasks",x=>[x.title,x.details]],["Projects",state.projects||[],"projects",x=>[x.name,x.outcome,x.criteria]],["Research",state.researchDrafts||[],"research",x=>[x.question]],["Learning",state.learningPlans||[],"learning",x=>[x.topic,x.goal]],["Conversations",state.conversations||[],"chat",x=>[x.title,...(x.chat||[]).slice(-6).map(m=>htmlText(m.html))]]];const results=[];for(const [label,items,view,fields] of sources){for(const item of items){const text=fields(item).filter(Boolean).join(" ");if(text.toLowerCase().includes(q)){results.push({label,view,title:String(item.title||item.name||item.topic||item.question||"Untitled"),detail:text.replace(/\\s+/g," ").slice(0,120)});if(results.length===10)break;}}if(results.length===10)break;}const html=results.map(r=>'<button type="button" class="global-search-result" data-view="'+r.view+'"><strong>'+escapeHTML(r.title)+'</strong><small>'+escapeHTML(r.label+" · "+r.detail)+'</small></button>').join("")||'<div class="global-search-empty">No matching saved items.</div>';box=document.createElement("div");box.className="global-search-results";box.innerHTML=html;$(".global-search")?.append(box);}
