  function updateRobotArm(panel){const l1=Number(panel?.dataset.link1)||1,l2=Number(panel?.dataset.link2)||1;const a=Number($(`input[data-angle="1"]`,panel)?.value||45)*Math.PI/180,b=Number($(`input[data-angle="2"]`,panel)?.value||35)*Math.PI/180,x1=l1*Math.cos(a),y1=l1*Math.sin(a),x2=x1+l2*Math.cos(a+b),y2=y1+l2*Math.sin(a+b),p=(x,y)=>x.toFixed(4)+" "+(-y).toFixed(4);const one=$("[data-arm-link1]",panel),two=$("[data-arm-link2]",panel),elbow=$("[data-arm-elbow]",panel),tip=$("[data-arm-tip]",panel);if(one)one.setAttribute("d","M 0 0 L "+p(x1,y1));if(two)two.setAttribute("d","M "+p(x1,y1)+" L "+p(x2,y2));if(elbow){elbow.setAttribute("cx",x1);elbow.setAttribute("cy",-y1);}if(tip){tip.setAttribute("cx",x2);tip.setAttribute("cy",-y2);}const o1=$("[data-angle1]",panel),o2=$("[data-angle2]",panel),co=$("[data-arm-coordinates]",panel);if(o1)o1.textContent=Math.round(a*180/Math.PI)+"°";if(o2)o2.textContent=Math.round(b*180/Math.PI)+"°";if(co)co.textContent="("+x2.toFixed(3)+", "+y2.toFixed(3)+")";}
  function applyTaskFilters(){const list=$("#taskList");if(!list)return;const query=($("#taskSearch")?.value||"").trim().toLowerCase(),filter=$("#taskStatusFilter")?.value||"all",sort=$("#taskSort")?.value||"due";const rows=$$("[data-task-row]",list);for(const row of rows){const status=row.dataset.status||"open",matchesText=!query||(row.dataset.search||"").includes(query),matchesStatus=filter==="all"||(filter==="overdue"?row.dataset.overdue==="true":filter===status);row.hidden=!(matchesText&&matchesStatus);}const visible=rows.filter(r=>!r.hidden);visible.sort((a,b)=>{const ta=state.tasks.find(t=>t.id===a.querySelector("[data-id]")?.dataset.id),tb=state.tasks.find(t=>t.id===b.querySelector("[data-id]")?.dataset.id);if(!ta||!tb)return 0;if(sort==="title")return String(ta.title||"").localeCompare(String(tb.title||""));if(sort==="created")return String(tb.createdAt||"").localeCompare(String(ta.createdAt||""));if(sort==="priority"){const rank={urgent:0,high:1,medium:2,low:3};return (rank[ta.priority]??2)-(rank[tb.priority]??2);}return (ta.dueDate||"9999-99-99").localeCompare(tb.dueDate||"9999-99-99")||String(tb.createdAt||"").localeCompare(String(ta.createdAt||""));});for(const row of visible)list.append(row);const count=$("#taskVisibleCount");if(count)count.textContent=String(visible.length);const empty=$("#taskFilterEmpty");if(empty)empty.hidden=visible.length>0;const all=$("#taskSelectAll");if(all){all.checked=visible.length>0&&visible.every(r=>r.querySelector("input[data-task-select]")?.checked);all.indeterminate=visible.some(r=>r.querySelector("input[data-task-select]")?.checked)&&!all.checked;}}
